    '\n'
    'def _is_proportional(source: tuple[int, ...], target: tuple[int, ...]) -> bool:\n'
    '    """Whether the gaps of `target` are those of `source` scaled by one positive factor."""\n'
    '    if len(source) < 2:\n'
    '        return True\n'
    '    (s0, s1), (t0, t1) = source[:2], target[:2]\n'
    '    return t1 > t0 and all((t - t0) * (s1 - s0) == (t1 - t0) * (s - s0) for s, t in zip(source, target, strict=True))\n'
