    '        if len(site) != 2 or not all(isinstance(c, Integral) and not isinstance(c, bool) for c in site):\n'
    '            msg = f"Qubit {qubit}: site must be an integer (x, y) pair, got {site!r}."\n'
    '            raise ArchitectureError(msg, "loading")\n'
    '        result[qubit] = (int(site[0]), int(site[1]))\n'
    '        if not zone_contains(zone, result[qubit]):\n'
    '            msg = f"Qubit {qubit} is loaded at {result[qubit]}, outside the {zone.name!r} zone."\n'
    '            raise ArchitectureError(msg, "loading")\n'
    '    if len(set(result.values())) != len(result):\n'
    '        msg = "Initial loading places more than one qubit on the same site."\n'
    '        raise ArchitectureError(msg, "loading")\n'
    '    return result\n'
