    'class ValidationArchitecture:\n'
    '    """The validator\'s zones with a participant\'s initial loading; replays circuits on them."""\n'
    '\n'
    '    def __init__(self, zones: dict[str, Zone], loading_zone: str, initial_loading: dict[int, Site]) -> None:\n'
    '        self.zones = zones\n'
    '        self.loading_zone = loading_zone\n'
    '        self.initial_loading = _validate_loading(initial_loading, zones[loading_zone])\n'
    '        self.zone_at: dict[Site, Zone] = {}\n'
    '        for zone in reversed(zones.values()):  # the first zone containing a site wins\n'
