    '\n'
    'def layout_from_steps(n, hub, steps):\n'
    '    """Atoms in order of first use, filled from storage row 9 upwards; first-round pairs adjacent."""\n'
    '    order = []\n'
    '    seen = set()\n'
    '    for kind, blks in steps:\n'
    '        for b in blks:\n'
    '            for q in (b.c, b.t) if kind == "round" else ((b.t if b.c == hub else b.c),):\n'
    '                if q not in seen:\n'
    '                    seen.add(q)\n'
    '                    order.append(q)\n'
    '    order += [q for q in range(n) if q not in seen and q != hub]\n'
