    '    order = [q for q in order if q != hub] + [hub]\n'
    '    home = {}\n'
    '    for i, q in enumerate(order):\n'
    '        home[q] = (i % 10, 9 - i // 10)\n'
    '    return home\n'
    '\n'
    '\n'
    'def next_partners(steps):\n'
    '    """nx[k][q] = q\'s partner in the first step after k that involves q."""\n'
    '    nx = [None] * len(steps)\n'
    '    cur = {}\n'
    '    for k in range(len(steps) - 1, -1, -1):\n'
    '        nx[k] = dict(cur)\n'
    '        for b in steps[k][1]:\n'
    '            cur[b.c] = b.t\n'
    '            cur[b.t] = b.c\n'
    '    return nx\n'
    '\n'
    '\n'
    'POLICIES = [("look", 2.0), ("look", 0.0), ("look", 1.0), ("look", 4.0), ("thresh", 8), ("thresh", 16), ("thresh", 30), ("thresh", 45), ("rounds",), ("look", 2.0, True, 8), ("look", 2.0, True, 20), ("look", 4.0, True, 12), ("thresh", 20, True), ("thresh", 30, True), ("thresh", 45, True), ("rounds", 0, True)]\n'
