    '\n'
    '\n'
    'def run_candidate(n, blocks, preds, succs, home, pol, lam, mu, opts=(), emit=False, allowed=None):\n'
    '    hub = n - 1\n'
    '    ex = Executor(n, hub, home, emit=emit)\n'
    '    ex.allowed = allowed if allowed is not None else frozenset(frozenset(b.qubits()) for b in blocks)\n'
    '    ex.LOOK = lam\n'
    '    for k, v in opts:\n'
    '        setattr(ex, k, v)\n'
    '    if ex.SEED is not None:\n'
    '        ex.rng = np.random.default_rng(ex.SEED)\n'
